    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_1,'speak',11,v_t_6,NULL,'پس بعد از کلاس به شعبهٔ پست می‌روم.','بدون دیدن متن آلمانی، پاسخ را با صدای خودت بگو.',1,CAST('{"mode":"recall_hidden","cue_fa":"پس بعد از کلاس به شعبهٔ پست می‌روم.","cueFa":"پس بعد از کلاس به شعبهٔ پست می‌روم.","accepted":["Dann gehe ich nach dem Kurs zur Postfiliale.","Nach dem Kurs hole ich das Paket ab.","Heute gehe ich noch zur Post."],"input":"speech","audioReveal":"after_attempt","textVisible":false,"scored":true,"independent":true}' AS JSON),JSON_OBJECT('contractMode','recall_hidden','typing',FALSE,'series',13));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_1,'speak',12,v_t_8,NULL,'خوب است، بسته نباید زیاد منتظر بماند.','بدون دیدن متن آلمانی، پاسخ را با صدای خودت بگو.',1,CAST('{"mode":"recall_hidden","cue_fa":"خوب است، بسته نباید زیاد منتظر بماند.","cueFa":"خوب است، بسته نباید زیاد منتظر بماند.","accepted":["Gut, das Paket muss nicht lange warten.","Ich hole das Paket heute ab.","Das Paket wartet nur bis heute."],"input":"speech","audioReveal":"after_attempt","textVisible":false,"scored":true,"independent":true}' AS JSON),JSON_OBJECT('contractMode','recall_hidden','typing',FALSE,'series',13));
