    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_3,'speak',17,NULL,NULL,'پشت باجه هستی و کارمند دلیل مراجعه‌ات را می‌پرسد؛ درخواست دریافت مرسوله را بگو.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"پشت باجه هستی و کارمند دلیل مراجعه‌ات را می‌پرسد؛ درخواست دریافت مرسوله را بگو.","scenario_fa":"پشت باجه هستی و کارمند دلیل مراجعه‌ات را می‌پرسد؛ درخواست دریافت مرسوله را بگو.","accepted":["Ich möchte meine Sendung abholen.","Ich bin hier, um mein Paket zu erhalten."],"acceptedIntents":["Ich möchte meine Sendung abholen.","Ich bin hier, um mein Paket zu erhalten."],"accepted_intents":["Ich möchte meine Sendung abholen.","Ich bin hier, um mein Paket zu erhalten."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":false,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',13));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_3,'speak',18,NULL,NULL,'کارمند می‌خواهد مطمئن شود بسته برای تو است؛ بگو نامت روی مرسوله نوشته شده.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"کارمند می‌خواهد مطمئن شود بسته برای تو است؛ بگو نامت روی مرسوله نوشته شده.","scenario_fa":"کارمند می‌خواهد مطمئن شود بسته برای تو است؛ بگو نامت روی مرسوله نوشته شده.","accepted":["Mein Name steht auf der Sendung.","Ich bin die Empfängerin dieses Pakets."],"acceptedIntents":["Mein Name steht auf der Sendung.","Ich bin die Empfängerin dieses Pakets."],"accepted_intents":["Mein Name steht auf der Sendung.","Ich bin die Empfängerin dieses Pakets."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":false,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',13));
