    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',11,v_t_6,NULL,'خوب است، آن را با خودم می‌برم.','بدون دیدن متن آلمانی، پاسخ را با صدای خودت بگو.',1,CAST('{"mode":"recall_hidden","cue_fa":"خوب است، آن را با خودم می‌برم.","cueFa":"خوب است، آن را با خودم می‌برم.","accepted":["Gut, ich nehme es mit.","Ich behalte das Paket.","Dann bringe ich den Karton nach Hause."],"input":"speech","audioReveal":"after_attempt","textVisible":false,"scored":true,"independent":true}' AS JSON),JSON_OBJECT('contractMode','recall_hidden','typing',FALSE,'series',13));
