    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',17,NULL,NULL,'گوشهٔ بسته آسیب دیده است؛ پیش از تحویل‌گرفتن اجازهٔ بررسی محتویات را بخواه.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"گوشهٔ بسته آسیب دیده است؛ پیش از تحویل‌گرفتن اجازهٔ بررسی محتویات را بخواه.","scenario_fa":"گوشهٔ بسته آسیب دیده است؛ پیش از تحویل‌گرفتن اجازهٔ بررسی محتویات را بخواه.","accepted":["Darf ich den Inhalt prüfen?","Kann ich das Paket bitte öffnen und kontrollieren?"],"acceptedIntents":["Darf ich den Inhalt prüfen?","Kann ich das Paket bitte öffnen und kontrollieren?"],"accepted_intents":["Darf ich den Inhalt prüfen?","Kann ich das Paket bitte öffnen und kontrollieren?"],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":true,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',13));
    INSERT INTO activities (lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES (v_l_4,'speak',18,NULL,NULL,'محتویات سالم است و رسید می‌خواهی؛ سالم‌بودن بسته را بگو و رسید درخواست کن.','در موقعیت تازه، پاسخ مناسب را با صدای خودت بگو.',1,CAST('{"mode":"scenario_transfer","scenarioFa":"محتویات سالم است و رسید می‌خواهی؛ سالم‌بودن بسته را بگو و رسید درخواست کن.","scenario_fa":"محتویات سالم است و رسید می‌خواهی؛ سالم‌بودن بسته را بگو و رسید درخواست کن.","accepted":["Der Inhalt ist in Ordnung, bitte geben Sie mir die Quittung.","Alles ist gut, ich möchte eine Quittung."],"acceptedIntents":["Der Inhalt ist in Ordnung, bitte geben Sie mir die Quittung.","Alles ist gut, ich möchte eine Quittung."],"accepted_intents":["Der Inhalt ist in Ordnung, bitte geben Sie mir die Quittung.","Alles ist gut, ich möchte eine Quittung."],"input":"speech","audioRequired":false,"textVisible":false,"scored":true,"independent":true,"masteryCheck":true,"cumulativeMastery":false}' AS JSON),JSON_OBJECT('contractMode','scenario_transfer','typing',FALSE,'series',13));
  ELSEIF v_count=1 THEN
    IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 OR (SELECT COUNT(*) FROM turns t JOIN lessons l ON l.id=t.lesson_id WHERE l.chapter_id=v_chapter)<>47 OR (SELECT COUNT(*) FROM activities a JOIN lessons l ON l.id=a.lesson_id WHERE l.chapter_id=v_chapter)<>72 OR JSON_UNQUOTE(JSON_EXTRACT((SELECT metadata FROM chapters WHERE id=v_chapter),'$.stageId'))<>'de-fa-a1-series-0013' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Existing chapter does not match the validated stage'; END IF;
  ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter identity is not unique'; END IF;
  SELECT id INTO v_chapter FROM chapters WHERE module_id=v_module AND sort_order=13;
  IF (SELECT COUNT(*) FROM lessons WHERE chapter_id=v_chapter)<>4 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Chapter must contain exactly four lessons'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN turns t ON t.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(t.id)<8 OR COUNT(t.id)>14) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Turn quota failed'; END IF;
  IF EXISTS (SELECT 1 FROM lessons l LEFT JOIN activities a ON a.lesson_id=l.id WHERE l.chapter_id=v_chapter GROUP BY l.id HAVING COUNT(a.id)<>18) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Activity quota failed'; END IF;
  COMMIT;
END$$
CALL import_nova_series_013()$$
DROP PROCEDURE IF EXISTS import_nova_series_013$$
DELIMITER ;
